  <div class="nw-row"><label>Vehicles</label><div class="nw-in"><span class="pfx">$</span><input type="number" class="nwA" min="0" step="500" inputmode="decimal" placeholder="0"></div></div>
  <div class="nw-row"><label>Other assets</label><div class="nw-in"><span class="pfx">$</span><input type="number" class="nwA" min="0" step="100" inputmode="decimal" placeholder="0"></div></div>
